import {evaluateBatch,effectiveWindow,validateBatch,migrateBatch} from './batch-model.mjs';
import {departmentTag} from './department-ui.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const key='fieldwork-decision-plans';
export class BatchWorkspace{
 constructor(o){this.o=o;this.cache=null;document.addEventListener('click',e=>{if(e.target.closest('[data-batch-open]'))this.open()});}
 evaluation(){const m=this.o.model(),ids=[...this.o.selected()].sort(),signature=ids.join('|');if(this.cache?.m!==m||this.cache?.signature!==signature)this.cache={m,signature,value:evaluateBatch(m,ids)};return this.cache.value;}
 summaryHTML(){const e=this.evaluation(),formal=this.o.formal();return `<section class="panel"><div class="panelhead"><h2>共同開工候選 <span>${e.selected.size}</span></h2></div><div class="detail batch-preview" data-no-dept-tag><div class="batch-metrics"><b>${e.departments.size}<small>責任部門</small></b><b>${e.selected.size}<small>產品</small></b><b>+${e.unlocked.length}<small>整批完成後新增前置就緒</small></b></div><ol class="batch-stages"><li>${[...e.selected].filter(id=>formal.results.get(id).candidate).length}／${e.selected.size} 正式前置已就緒</li><li>資源／窗口：尚未確認</li><li>正式部署計畫：尚未串接</li></ol><p>${e.check.pairs.length?'批次內有 '+e.check.pairs.length+' 組必要先後牽制，建議拆為 '+e.waves.length+' 波次。':'未發現選取產品間的必要順序；仍需確認資源與窗口。'}</p>${e.cyclic.length?'<p class="red">有循環成員無法排入波次，需先解除循環。</p>':''}<details><summary>產品明細（${e.selected.size}）</summary>${this.groups([...e.selected],false)}</details><button class="primary" data-batch-open ${e.selected.size?'':'disabled'}>管理部署批次</button><p class="small">效益以目前試算為比較基準；前置就緒不等於資源可用。</p></div></section>`;}
 groups(ids,editable=true){const m=this.o.model(),groups=new Map();for(const id of ids){const n=m.by.get(id);if(!n)continue;if(!groups.has(n.department_name))groups.set(n.department_name,[]);groups.get(n.department_name).push(n)}return [...groups].map(([dept,nodes])=>`<details class="batch-department"><summary>${esc(dept)} · ${nodes.length} 項</summary>${nodes.map(n=>{const w=this.draft?effectiveWindow(this.draft,n.id):null;return `<div class="batch-product"><div><b>${esc(n.product_name)}</b>${departmentTag(n)}<small>${m.results.get(n.id).candidate?'前置就緒':m.results.get(n.id).execution==='done'?'部署已完成':'尚有前置條件'}${this.draft?.exceptions[n.id]?' · 個別窗口':''}</small></div>${editable?`<button data-batch-exception="${n.id}">個別例外</button><button data-batch-remove="${n.id}">移除</button><div class="batch-exception" ${this.draft.exceptions[n.id]?'':'hidden'} data-exception-row="${n.id}"><label>開始<input type="datetime-local" data-batch-start="${n.id}" value="${esc(w.start)}"></label><label>結束<input type="datetime-local" data-batch-end="${n.id}" value="${esc(w.end)}"></label><button data-batch-inherit="${n.id}">恢復共用窗口</button></div>`:''}</div>`}).join('')}</details>`).join('')}
 open(plan){if(this.host)this.close();this.o.closeDrawer?.();const m=this.o.model();this.draft=migrateBatch(plan||{name:'部署批次草案',factory:m.ctx.factory.factory_id,profile:m.ctx.profile,selected:[...this.o.selected()],trial:[...m.trial],snapshot:m.ctx.factory.snapshot_at});this.returnFocus=document.activeElement;this.host=document.createElement('section');this.host.id='batchDesk';this.host.setAttribute('data-no-dept-tag','');this.host.className='management-overlay';this.host.setAttribute('role','dialog');this.host.setAttribute('aria-modal','true');this.host.setAttribute('aria-label','部署批次管理');document.body.append(this.host);document.body.classList.add('management-open');for(const el of document.querySelectorAll('main,#rail'))el.inert=true;this.host.addEventListener('click',e=>this.click(e));this.host.addEventListener('change',e=>this.change(e));this.host.addEventListener('keydown',e=>{if(e.key==='Escape')this.close()});this.render();this.host.querySelector('button').focus();}
 load(plan){this.o.loadScope(plan);this.open(plan)}
 close(){this.host?.remove();this.host=null;document.body.classList.remove('management-open');for(const el of document.querySelectorAll('main,#rail'))el.inert=false;this.returnFocus?.isConnected&&this.returnFocus.focus({preventScroll:true});}
 render(){const d=this.draft,m=this.o.model(),f=this.o.formal(),e=evaluateBatch(m,d.selected),formalReady=d.selected.filter(id=>f.results.get(id)?.candidate).length;this.host.innerHTML=`<header class="management-header"><div><small>DEPLOYMENT BATCH · ${esc(m.ctx.factory.factory_name)}</small><h2>部署批次管理</h2></div><button data-batch-close>返回工作台</button></header><div class="batch-body"><section class="batch-summary"><div class="batch-metrics"><b>${e.departments.size}<small>部門</small></b><b>${e.selected.size}<small>產品</small></b><b>+${e.unlocked.length}<small>整批完成後新增前置就緒</small></b></div><ol class="batch-stages"><li class="${formalReady===d.selected.length&&d.selected.length?'green':''}">前置已就緒：${formalReady}／${d.selected.length}（正式快照）</li><li>資源／窗口：${{unreviewed:'尚未評估',confirmed:'人工已確認',conflict:'有衝突待協調'}[d.resource]}</li><li>${d.planRef?(validateBatch(d,m,f).length?'草案計畫關聯待確認：':'已記錄計畫關聯（人工）：')+esc(d.planRef):'已納入部署計畫：尚未串接正式系統'}</li></ol><p data-batch-window>預計窗口：${d.start&&d.end?esc(d.start.replace('T',' '))+' ～ '+esc(d.end.replace('T',' ')):'尚未設定共用窗口'} · 個別例外 ${Object.keys(d.exceptions).length} 項</p>${m.trial.size?'<div class="notice">目前有完成假設；新增就緒效益為試算。正式前置數與計畫關聯仍依原始快照檢查。</div>':''}<details><summary>預期解鎖產品（${e.unlocked.length}）／${new Set(e.unlocked.map(r=>r.node.department_id)).size} 個部門</summary>${this.groups(e.unlocked.map(r=>r.node.id),false)}</details><details><summary>必要順序與拆批建議</summary><p>${e.check.verdict}</p>${e.waves.map((ids,i)=>`<div class="batch-wave">波次 ${i+1} · ${ids.length} 項<button data-batch-wave="${i}">以此波次另存草案</button></div>`).join('')}<p>${e.cyclic.length?e.cyclic.length+' 項仍在循環／受循環牽制，未排入波次。':''}波次只表示依賴順序；後續波次仍需等前置完成，不代表目前可以開工。</p></details><h3>已保存批次</h3>${this.savedHTML()}</section><section class="batch-editor"><h3>批次設定</h3><div class="batch-fields"><label>批次名稱<input data-batch-field="name" value="${esc(d.name)}"></label><label>共用開始窗口<input type="datetime-local" data-batch-field="start" value="${esc(d.start)}"></label><label>共用結束窗口<input type="datetime-local" data-batch-field="end" value="${esc(d.end)}"></label><label>資源確認<select data-batch-field="resource">${[['unreviewed','尚未評估'],['confirmed','人工已確認'],['conflict','有衝突待協調']].map(([v,t])=>`<option value="${v}" ${v===d.resource?'selected':''}>${t}</option>`).join('')}</select></label><label>確認人／責任團隊<input data-batch-field="owner" value="${esc(d.owner)}"></label><label>確認依據／衝突事項<textarea data-batch-field="resourceNote">${esc(d.resourceNote)}</textarea></label><label>既有正式計畫編號（選填）<input data-batch-field="planRef" value="${esc(d.planRef)}" placeholder="僅記錄人工關聯，非正式排程寫入"></label></div><p class="small">共用窗口僅套用至無個別例外的產品；時間以工廠時區 ${esc(m.ctx.factory.timezone)} 記錄。沒有資源容量資料，不自動判定無衝突。</p><details><summary>產品明細與個別例外（${d.selected.length}）</summary><label>搜尋產品／部門<input id="batchProductSearch" placeholder="輸入名稱…"></label><div id="batchProducts">${this.groups(d.selected)}</div></details><div id="batchErrors" role="alert"></div><div class="batch-save"><button class="primary" data-batch-save>保存本機批次草案</button><button data-batch-export>匯出此批次</button></div><p class="small">本機草案不等於正式部署計畫；資源／窗口的人工確認可撤回，產品前置變動後需重新檢查。</p></section></div>`;this.host.querySelector('#batchProductSearch').oninput=event=>{const q=event.target.value.toLowerCase();this.host.querySelectorAll('.batch-editor .batch-product').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q));this.host.querySelectorAll('.batch-editor .batch-department').forEach(g=>{g.open=!!q;g.hidden=![...g.querySelectorAll('.batch-product')].some(r=>!r.hidden)})};}
 savedHTML(){let plans=[];try{plans=JSON.parse(localStorage.getItem(key)||'[]')}catch{}return plans.filter(p=>p.factory===this.draft.factory).map(p=>`<div class="batch-saved"><span>${esc(p.name)}<small>${p.selected.length} 項 · 本機草案</small></span><button data-batch-load="${p.id}">載入</button></div>`).join('')||'<p class="small">尚未保存批次。</p>'}
 read(){for(const input of this.host.querySelectorAll('[data-batch-field]'))this.draft[input.dataset.batchField]=input.value;}
 change(e){const t=e.target;if(t.dataset.batchField){this.read();if(t.dataset.batchField==='resource')this.draft.confirmedAt=t.value==='confirmed'?new Date().toISOString():null;if(['start','end'].includes(t.dataset.batchField))this.invalidateConfirmation();this.updateResourceSummary();return}const id=t.dataset.batchStart||t.dataset.batchEnd;if(id){this.draft.exceptions[id]||={...effectiveWindow(this.draft,id)};this.draft.exceptions[id][t.dataset.batchStart?'start':'end']=t.value;this.invalidateConfirmation();this.updateResourceSummary();}}
 invalidateConfirmation(){this.draft.resource='unreviewed';this.draft.confirmedAt=null;const select=this.host.querySelector('[data-batch-field=resource]');if(select)select.value='unreviewed'}
 updateResourceSummary(){const windowRow=this.host.querySelector('[data-batch-window]');if(windowRow)windowRow.textContent='預計窗口：'+(this.draft.start&&this.draft.end?this.draft.start.replace('T',' ')+' ～ '+this.draft.end.replace('T',' '):'尚未設定共用窗口')+' · 個別例外 '+Object.keys(this.draft.exceptions).length+' 項';const row=this.host.querySelector('.batch-stages li:nth-child(2)');if(row)row.textContent='資源／窗口：'+({unreviewed:'尚未評估',confirmed:'人工已確認',conflict:'有衝突待協調'}[this.draft.resource])}
 click(e){const b=e.target.closest('button');if(!b)return;this.read();const d=this.draft;if(b.hasAttribute('data-batch-close'))return this.close();if(b.dataset.batchRemove){d.selected=d.selected.filter(id=>id!==b.dataset.batchRemove);delete d.exceptions[b.dataset.batchRemove];this.invalidateConfirmation();this.render()}if(b.dataset.batchException){const id=b.dataset.batchException;d.exceptions[id]||={start:d.start,end:d.end};const row=this.host.querySelector('[data-exception-row="'+id+'"]');row.hidden=false;row.querySelector('[data-batch-start]').value=d.exceptions[id].start;row.querySelector('[data-batch-end]').value=d.exceptions[id].end}if(b.dataset.batchInherit){delete d.exceptions[b.dataset.batchInherit];this.invalidateConfirmation();this.render()}if(b.dataset.batchWave!==undefined){const e=evaluateBatch(this.o.model(),d.selected),wave=e.waves[Number(b.dataset.batchWave)];this.draft={...d,id:null,name:d.name+' · 波次 '+(Number(b.dataset.batchWave)+1),selected:wave,exceptions:Object.fromEntries(Object.entries(d.exceptions).filter(([id])=>wave.includes(id))),resource:'unreviewed',planRef:''};this.render()}if(b.dataset.batchLoad){const plan=JSON.parse(localStorage.getItem(key)||'[]').find(p=>String(p.id)===b.dataset.batchLoad);if(plan)this.load(plan)}if(b.hasAttribute('data-batch-save')){const errors=validateBatch(d,this.o.model(),this.o.formal());if(errors.length){this.host.querySelector('#batchErrors').innerHTML=errors.map(x=>'<p>'+esc(x)+'</p>').join('');return}d.id ||= Date.now();d.updatedAt=new Date().toISOString();d.snapshot=this.o.model().ctx.factory.snapshot_at;d.verdict=evaluateBatch(this.o.model(),d.selected).check.verdict;d.trial=[...this.o.model().trial];d.dates=Object.fromEntries(d.selected.map(id=>[id,effectiveWindow(d,id).start.slice(0,10)]));try{const plans=JSON.parse(localStorage.getItem(key)||'[]').filter(p=>p.id!==d.id);plans.unshift(d);localStorage.setItem(key,JSON.stringify(plans));this.o.saved();this.o.toast('批次草案已保存於本機');this.render()}catch{this.o.toast('本機儲存失敗，請匯出批次')}}if(b.hasAttribute('data-batch-export')){const ev=evaluateBatch(this.o.model(),d.selected),data={...d,synthetic:true,storage:'browser-local-draft',formalPlanIntegrated:false,unlockedProducts:ev.unlocked.map(r=>({id:r.node.id,name:r.node.product_name,department:r.node.department_name})),errors:validateBatch(d,this.o.model(),this.o.formal())};this.o.download(data,'deployment-batch.json')}}
}
